  ["STRINGID_PKMNBOXSOMEONESPCFULL"] = "A CAIXA “{STR_VAR_3}” do\\nPC de Alguém estava cheia.\\p{STR_VAR_2} foi transferido para\\na CAIXA “{STR_VAR_1}.”",
