  ["SevenIsland_SevaultCanyon_Entrance_Text_MiahRematchIntro"] = "Kyahaha!\\pVoltar não vai mudar nada.\\nVou te derrotar num piscar de olhos!",
  ["SevenIsland_SevaultCanyon_Entrance_Text_NicolasRematchIntro"] = "Esta ilha é grande demais…\\nPatrulhar este lugar é um saco…",
  ["SevenIsland_SevaultCanyon_Text_CyndyRematchIntro"] = "Vamos batalhar de novo.\\nEstou em plena forma!",
  ["SevenIsland_SevaultCanyon_Text_EvanRematchIntro"] = "Não importa se você por acaso\\ntem os POKéMON mais fortes…\\pNão significa nada se você não\\nsouber usá-los direito!",
  ["SevenIsland_SevaultCanyon_Text_JacksonRematchIntro"] = "Eu trabalho para proteger o meio\\nambiente.\\pEm troca, a natureza me protege!",
  ["SevenIsland_SevaultCanyon_Text_KatelynRematchIntro"] = "Toda vez que a gente se vê, você\\nestá com esses calçados estilosos.",
  ["SevenIsland_SevaultCanyon_Text_LeroyRematchIntro"] = "Você deve ter ficado mais forte.\\pDeixa eu batalhar com você,\\npor favor!",
  ["SevenIsland_SevaultCanyon_Text_LexRematchIntro"] = "LEX: Minha querida NYA, juntos\\nvenceremos com certeza!",
  ["SevenIsland_SevaultCanyon_Text_MichelleRematchIntro"] = "Recebi a melhor educação possível\\npara me tornar assim tão forte.\\pNão vou perder desta vez.\\nCom certeza não!",
  ["SevenIsland_SevaultCanyon_Text_NyaRematchIntro"] = "NYA: Não vou decepcionar meu\\nmentor LEX! Nós vamos vencer!",
  ["SevenIsland_TanobyRuins_Text_BenjaminRematchIntro"] = "Dizem que um POKéMON místico\\ndorme aqui dentro.",
