  ["SevenIsland_TanobyRuins_Text_CliffordRematchIntro"] = "Hoje, além da nossa aula, viemos\\nver a câmara novamente.",
  ["SevenIsland_TanobyRuins_Text_EdnaRematchIntro"] = "Meu professor está me ensinando a\\npintar um pouco mais.",
  ["SevenIsland_TrainerTower_Text_DarioRematchIntro"] = "Senti sua aproximação.",
