  ["SixIsland_GreenPath_Text_JaclynRematchIntro"] = "… Hã?\\pEu penso na minha casa, mas\\nsempre me TELEPORTO pra cá!",
  ["SixIsland_OutcastIsland_Text_AvaRematchIntro"] = "AVA: Vamos ter outra batalha\\nmarinha de dois contra dois hoje!",
  ["SixIsland_OutcastIsland_Text_GebRematchIntro"] = "GEB: Minha irmã e eu estamos muito\\nmais fortes do que antes!",
  ["SixIsland_OutcastIsland_Text_MymoRematchIntro"] = "Oof… Oof…\\pNadei do porto da SEIS ILHAS\\naté aqui direto, de novo.",
