  ["sEggHatchTimeTexts[0]"] = "Parece que este OVO\\nvai demorar muito\\ntempo para chocar.",
  ["sEggHatchTimeTexts[1]"] = "O que será que vai\\nchocar daqui? Vai\\nlevar algum tempo.",
