  ["sEggOriginTexts[6]"] = "Um OVO de POKéMON peculiar\\nobtido em uma troca.",
  ["sFameCheckerFlavorTextPointers[0]"] = "\252\001\008\252\003\009O que esta pessoa faz?\\p\252\001\002\252\003\003LABORATÓRIO de PESQUISA POKéMON",
  ["sFameCheckerFlavorTextPointers[10]"] = "\252\001\008\252\003\009Como é esta pessoa?\\p\252\006\005\252\001\002\252\003\003Uma garota da CIDADE DE PALLET,\\nDAISY, gosta de tomar CHÁ todos\\los dias.\\pEla visita o SHOPPING DE CELADON\\npra comprar CHÁ.",
  ["sFameCheckerFlavorTextPointers[11]"] = "\252\001\008\252\003\009Tem um boato…\\p\252\001\002\252\003\003A Grande Campeã do CONCURSO\\nPOKéMON de Primavera é a DAISY\\lCARVALHO da CIDADE DE PALLET!",
  ["sFameCheckerFlavorTextPointers[12]"] = "\252\001\008\252\003\009O que esta pessoa faz?\\p\252\001\002\252\003\003GINÁSIO POKéMON de PEWTER\\nLÍDER: BROCK\\lO TREINADOR de POKéMON inabaláveis!",
  ["sFameCheckerFlavorTextPointers[13]"] = "\252\001\008\252\003\009Tipo favorito de POKéMON?\\p\252\006\004\252\001\002\252\003\003Minha determinação inabalável\\nse reflete nos meus POKéMON.\\pTodos os meus POKéMON são \\nresistentes como pedras e têm\\lmuita determinação.\\pIsso mesmo! Todos os meus\\nPOKéMON são do tipo PEDRA!",
  ["sFameCheckerFlavorTextPointers[14]"] = "\252\001\008\252\003\009Como é esta pessoa?\\p\252\006\004\252\001\002\252\003\003Não tem muitos TREINADORES\\nPOKéMON sérios por aqui.\\pA maioria são como os CAÇA-INSETOS,\\nsabe, só amadores.\\pMas o BROCK do GINÁSIO de PEWTER\\né exceção.",
  ["sFameCheckerFlavorTextPointers[15]"] = "\252\001\008\252\003\009Como é esta pessoa?\\p\252\006\004\252\001\002\252\003\003Além de ser forte, o BROCK é uma\\nboa pessoa. Ele é respeitado e\\ladmirado.\\pEu quero ser um LÍDER de GINÁSIO\\ncomo ele.",
  ["sFameCheckerFlavorTextPointers[16]"] = "\252\001\008\252\003\009O que esta pessoa faz?\\p\252\006\004\252\001\002\252\003\003Oi, estou escavando fósseis sob o\\nMONTE LUA.\\pÀs vezes, o BROCK do GINÁSIO de\\nPEWTER me dá uma mãozinha.",
  ["sFameCheckerFlavorTextPointers[17]"] = "\252\001\008\252\003\009Como é esta pessoa?\\p\252\001\002\252\003\003BROCK raramente ri, mas dizem que\\nele não consegue parar se começar.",
  ["sFameCheckerFlavorTextPointers[18]"] = "\252\001\008\252\003\009O que esta pessoa faz?\\p\252\001\002\252\003\003GINÁSIO POKéMON de CERULEAN\\nLÍDER: MISTY\\lA sereia durona!",
  ["sFameCheckerFlavorTextPointers[19]"] = "\252\001\008\252\003\009Tipo favorito de POKéMON?\\p\252\006\005\252\001\002\252\003\003Minha tática é ofensiva total com\\nos POKéMON do tipo ÁGUA!",
  ["sFameCheckerFlavorTextPointers[1]"] = "\252\001\008\252\003\009Como é esta pessoa?\\p\252\006\004\252\001\002\252\003\003Eu queria fazer um guia completo\\nde todos os POKéMON do mundo…\\pEsse era o meu sonho!",
  ["sFameCheckerFlavorTextPointers[20]"] = "\252\001\008\252\003\009Como é esta pessoa?\\p\252\006\004\252\001\002\252\003\003A MISTY é uma TREINADORA que\\nestá sempre melhorando.\\pEla não vai perder pra alguém\\ncomo você!",
  ["sFameCheckerFlavorTextPointers[21]"] = "\252\001\008\252\003\009Tem um boato…\\p\252\006\004\252\001\002\252\003\003TREINADORES fortes e POKéMON de\\nÁGUA são muito comuns por aqui.\\pDizem que a MISTY do GINÁSIO de\\nCERULEAN treina neste lugar.",
  ["sFameCheckerFlavorTextPointers[22]"] = "\252\001\008\252\003\009Tem um boato…\\p\252\006\005\252\001\002\252\003\003Este cabo é um lugar famoso para\\nencontros.\\pMISTY, a LÍDER de GINÁSIO, adora\\neste lugar.",
  ["sFameCheckerFlavorTextPointers[23]"] = "\252\001\008\252\003\009Tem um boato…\\p\252\001\002\252\003\003Dizem que MISTY adora LORELEI,\\nda ELITE DOS QUATRO.",
  ["sFameCheckerFlavorTextPointers[24]"] = "\252\001\008\252\003\009O que esta pessoa faz?\\p\252\001\002\252\003\003GINÁSIO POKéMON de VERMILION\\nLÍDER: TEN. SURGE\\lO relâmpago americano!",
  ["sFameCheckerFlavorTextPointers[25]"] = "\252\001\008\252\003\009Tipo favorito de POKéMON?\\p\252\006\004\252\001\002\252\003\003Eu te digo, garot{o_a}, os POKéMON\\nelétricos me salvaram durante a\\lguerra!",
  ["sFameCheckerFlavorTextPointers[26]"] = "\252\001\008\252\003\009Como é esta pessoa?\\p\252\006\004\252\001\002\252\003\003Quando eu estava no Exército, o\\nTEN. SURGE era meu comandante\\lrígido.\\pEle era um chefe durão.",
  ["sFameCheckerFlavorTextPointers[27]"] = "\252\001\008\252\003\009Como é esta pessoa?\\p\252\006\004\252\001\002\252\003\003O TEN. SURGE sempre foi famoso por\\nsua natureza cautelosa no Exército.",
  ["sFameCheckerFlavorTextPointers[28]"] = "\252\001\008\252\003\009Como é esta pessoa?\\p\252\006\004\252\001\002\252\003\003O TEN. SURGE instalou as armadilhas\\nno GINÁSIO pessoalmente.\\pEle colocou travas duplas por todo\\nlado.",
  ["sFameCheckerFlavorTextPointers[29]"] = "\252\001\008\252\003\009Tem um boato…\\p\252\001\002\252\003\003Dizem que o TEN. SURGE foi piloto\\nenquanto vivia nos Estados Unidos.\\pEle usava a eletricidade gerada por\\nPOKéMON para mover seu avião.",
  ["sFameCheckerFlavorTextPointers[2]"] = "\252\001\008\252\003\009Como é esta pessoa?\\p\252\006\005\252\001\002\252\003\003Pode não parecer, mas o PROFESSOR\\nCARVALHO é especialista em\\lPOKéMON.\\pEle é admirado por muitos\\nTREINADORES POKéMON.",
  ["sFameCheckerFlavorTextPointers[30]"] = "\252\001\008\252\003\009O que esta pessoa faz?\\p\252\001\002\252\003\003GINÁSIO POKéMON de CELADON\\nLÍDER: ERIKA\\lA princesa amante da natureza!",
  ["sFameCheckerFlavorTextPointers[31]"] = "\252\001\008\252\003\009Tipo favorito de POKéMON?\\p\252\006\005\252\001\002\252\003\003Sou estudante da arte de arranjos\\nde flores.\\pMeus POKéMON são todos do tipo\\nPLANTA.",
  ["sFameCheckerFlavorTextPointers[32]"] = "\252\001\008\252\003\009Como é esta pessoa?\\p\252\006\005\252\001\002\252\003\003A nossa LÍDER ERIKA pode ser\\ndiscreta, mas ela é famosa por aqui.",
  ["sFameCheckerFlavorTextPointers[33]"] = "\252\001\008\252\003\009Como é esta pessoa?\\p\252\006\005\252\001\002\252\003\003No nosso GINÁSIO, só usamos\\nPOKéMON do tipo PLANTA.\\pPor quê? Também usamos eles\\npara fazer arranjos de flores!",
  ["sFameCheckerFlavorTextPointers[34]"] = "\252\001\008\252\003\009Tipo favorito de POKéMON?\\p\252\006\005\252\001\002\252\003\003Eu nunca colecionaria POKéMON\\nse eles não fossem bonitos.",
  ["sFameCheckerFlavorTextPointers[35]"] = "\252\001\008\252\003\009Tem um boato…\\p\252\001\002\252\003\003Dizem que, se você espiar o GINÁSIO\\nde CELADON, poderá ver ERIKA\\ltirando um cochilo.",
  ["sFameCheckerFlavorTextPointers[36]"] = "\252\001\008\252\003\009O que esta pessoa faz?\\p\252\001\002\252\003\003GINÁSIO POKéMON de FUCHSIA\\nLÍDER: KOGA\\lO mestre ninja venenoso",
  ["sFameCheckerFlavorTextPointers[37]"] = "\252\001\008\252\003\009Tipo favorito de POKéMON?\\p\252\006\004\252\001\002\252\003\003Desespere diante do horror dos\\nPOKéMON do tipo VENENO!",
  ["sFameCheckerFlavorTextPointers[38]"] = "\252\001\008\252\003\009Como é esta pessoa?\\p\252\006\004\252\001\002\252\003\003Mesmo tendo perdido, vou continuar\\ntreinando seguindo os ensinamentos\\lde KOGA, meu mestre ninja.",
  ["sFameCheckerFlavorTextPointers[39]"] = "\252\001\008\252\003\009Família e amigos?\\p\252\006\005\252\001\002\252\003\003Meu pai é o LÍDER de GINÁSIO\\ndesta cidade.\\pEstou treinando para usar POKéMON\\ndo tipo VENENO tão bem quanto ele.",
  ["sFameCheckerFlavorTextPointers[3]"] = "\252\001\008\252\003\009Família e amigos?\\p\252\001\002\252\003\003O PROFESSOR CARVALHO vive com\\nseus netos, DAISY e {RIVAL}.",
  ["sFameCheckerFlavorTextPointers[40]"] = "\252\001\008\252\003\009Tem um boato…\\p\252\001\002\252\003\003Dizem que KOGA possui um grande\\nconhecimento sobre medicina.\\pEle até prepara remédios para\\ncurar seus POKéMON.",
  ["sFameCheckerFlavorTextPointers[41]"] = "\252\001\008\252\003\009O que esta pessoa faz?\\p\252\006\004\252\001\002\252\003\003A ZONA DE SAFÁRI é enorme,\\nnão acha?\\pO LÍDER do GINÁSIO de FUCHSIA,\\nKOGA, patrulha a área de vez em\\lquando.\\pGraças a ele, podemos brincar aqui\\nsabendo que estamos seguros.",
  ["sFameCheckerFlavorTextPointers[42]"] = "\252\001\008\252\003\009O que esta pessoa faz?\\p\252\001\002\252\003\003GINÁSIO POKéMON de SAFFRON\\nLÍDER: SABRINA\\lA mestra dos POKéMON PSÍQUICOS!",
  ["sFameCheckerFlavorTextPointers[43]"] = "\252\001\008\252\003\009Tipo favorito de POKéMON?\\p\252\006\004\252\001\002\252\003\003Você conhece a LÍDER de GINÁSIO\\nda CIDADE DE SAFFRON?\\pEla usa POKéMON do tipo\\nPSÍQUICO, né?",
  ["sFameCheckerFlavorTextPointers[44]"] = "\252\001\008\252\003\009Como é esta pessoa?\\p\252\006\005\252\001\002\252\003\003Tenho poderes psíquicos desde\\ncriança.\\pTudo começou quando entortei uma\\ncolher sem querer.",
  ["sFameCheckerFlavorTextPointers[45]"] = "\252\001\008\252\003\009Como é esta pessoa?\\p\252\006\005\252\001\002\252\003\003Não gosto de batalhas, mas se você\\nquiser, mostrarei meus poderes!",
  ["sFameCheckerFlavorTextPointers[46]"] = "\252\001\008\252\003\009Tem um boato…\\p\252\001\002\252\003\003Dizem que SABRINA consegue se\\ncomunicar com seus POKéMON em\\lbatalha sem falar nada.",
  ["sFameCheckerFlavorTextPointers[47]"] = "\252\001\008\252\003\009Como é esta pessoa?\\p\252\006\004\252\001\002\252\003\003A SABRINA acabou de derrotar o\\nMESTRE de CARATÊ ao lado.",
  ["sFameCheckerFlavorTextPointers[48]"] = "\252\001\008\252\003\009O que esta pessoa faz?\\p\252\001\002\252\003\003GINÁSIO POKéMON de CINNABAR\\nLÍDER: BLAINE\\lO mestre das perguntas impulsivo!",
  ["sFameCheckerFlavorTextPointers[49]"] = "\252\001\008\252\003\009Tipo favorito de POKéMON?\\p\252\006\004\252\001\002\252\003\003Meus POKéMON de fogo são todos\\ncasca-grossa e estão sempre\\lprontos pra esquentar as coisas!\\pEles incineram qualquer desafiante!",
  ["sFameCheckerFlavorTextPointers[4]"] = "\252\001\008\252\003\009Família e amigos?\\p\252\006\005\252\001\002\252\003\003Ouvi dizer que CARVALHO tem muita\\nadmiração por você, criança.\\pAquele velho rabugento já foi\\nforte e bonito.\\pMas isso foi há décadas.\\nEle é só uma sombra do que era.",
  ["sFameCheckerFlavorTextPointers[50]"] = "\252\001\008\252\003\009Tipo favorito de POKéMON?\\p\252\006\004\252\001\002\252\003\003Nosso LÍDER, BLAINE, se perdeu\\npra valer nas montanhas.\\pQuando anoiteceu, um POKéMON\\npássaro flamejante apareceu.\\pA luz dele permitiu que BLAINE\\nencontrasse o caminho de volta\\lem segurança.",
  ["sFameCheckerFlavorTextPointers[51]"] = "\252\001\008\252\003\009Como é esta pessoa?\\p\252\006\005\252\001\002\252\003\003BLAINE do GINÁSIO de CINNABAR\\né um cara bem estranho.\\pEle vive na ilha desde muito antes\\ndo LABORATÓRIO ser construído.",
  ["sFameCheckerFlavorTextPointers[52]"] = "\252\001\008\252\003\009Família e amigos?\\p\252\001\002\252\003\003É uma foto de BLAINE e do\\nSR. FUJI.\\pEles estão lado a lado, sorrindo\\nde orelha a orelha.",
  ["sFameCheckerFlavorTextPointers[53]"] = "\252\001\008\252\003\009Tem um boato…\\p\252\001\002\252\003\003Dizem que BLAINE só tira os seus\\nóculos escuros quando está bolando\\lnovas perguntas para o questionário.",
  ["sFameCheckerFlavorTextPointers[54]"] = "\252\001\008\252\003\009O que esta pessoa faz?\\p\252\006\005\252\001\002\252\003\003Sou LORELEI, da ELITE DOS QUATRO.",
  ["sFameCheckerFlavorTextPointers[55]"] = "\252\001\008\252\003\009Tipo favorito de POKéMON?\\p\252\006\005\252\001\002\252\003\003Ninguém é melhor do que eu quando\\nse trata de POKéMON de gelo.",
  ["sFameCheckerFlavorTextPointers[56]"] = "\252\001\008\252\003\009Onde esta pessoa nasceu?\\p\252\006\004\252\001\002\252\003\003Uma TREINADORA incrível e\\npoderosa cresceu nesta ilha.\\pAposto que até você conhece ela.\\nÉ a LORELEI da ELITE DOS QUATRO!",
  ["sFameCheckerFlavorTextPointers[57]"] = "\252\001\008\252\003\009Como é esta pessoa?\\p\252\001\002\252\003\003Conhecida por seu estilo de batalha\\nlógico, calculado e frio, LORELEI\\ltem um segredo surpreendente!",
  ["sFameCheckerFlavorTextPointers[58]"] = "\252\001\008\252\003\009Como é esta pessoa?\\p\252\006\005\252\001\002\252\003\003Você sabia que a LORELEI tem\\nmuitos, muitos bichos de pelúcia?\\pToda vez que ela volta pra ILHA\\nQUATRO, a coleção dela aumenta!",
  ["sFameCheckerFlavorTextPointers[59]"] = "\252\001\008\252\003\009Tipo favorito de POKéMON?\\p\252\006\005\252\001\002\252\003\003O LAPRAS que ela tem deve ser o\\nmesmo que ela conheceu quando\\lera criança.\\pAcho que ela o capturou na\\nCAVERNA GLACIAL.\\pTalvez esse POKéMON esteja com\\nela desde então.",
  ["sFameCheckerFlavorTextPointers[5]"] = "\252\001\008\252\003\009O que esta pessoa faz?\\p\252\006\004\252\001\002\252\003\003Em breve, o PROFESSOR CARVALHO\\nterá seu próprio programa de rádio.\\pO programa se chamará SEMINÁRIO\\nPOKéMON do PROFESSOR CARVALHO.",
  ["sFameCheckerFlavorTextPointers[60]"] = "\252\001\008\252\003\009O que esta pessoa faz?\\p\252\006\004\252\001\002\252\003\003Sou BRUNO, da ELITE DOS QUATRO!",
  ["sFameCheckerFlavorTextPointers[61]"] = "\252\001\008\252\003\009Tipo favorito de POKéMON?\\p\252\006\004\252\001\002\252\003\003Sempre vivi e treinei com meus\\nPOKéMON lutadores!",
  ["sFameCheckerFlavorTextPointers[62]"] = "\252\001\008\252\003\009Como é esta pessoa?\\p\252\001\002\252\003\003Parece que BRUNO se juntou à\\nELITE DOS QUATRO por sua ambição\\lde batalhar contra os melhores\\lTREINADORES.",
  ["sFameCheckerFlavorTextPointers[63]"] = "\252\001\008\252\003\009Como é esta pessoa?\\p\252\006\004\252\001\002\252\003\003BRUNO, que é mais experiente do\\nque eu, visita o SPA às vezes.\\pEle vem para tratar lesões, tanto\\nas dele quanto as dos POKéMON.",
  ["sFameCheckerFlavorTextPointers[64]"] = "\252\001\008\252\003\009Tem um boato…\\p\252\006\005\252\001\002\252\003\003Ele é um dos membros da ELITE\\nDOS QUATRO. O nome dele é BRUNO.\\pEle foi embora todo desapontado\\nquando descobriu que os DOCES\\lDA FÚRIA estavam esgotados.",
  ["sFameCheckerFlavorTextPointers[65]"] = "\252\001\008\252\003\009Família e amigos?\\p\252\006\004\252\001\002\252\003\003Até o BRUNO…\\nEle já treinou com um cara\\lchamado BRAWLY antes.",
  ["sFameCheckerFlavorTextPointers[66]"] = "\252\001\008\252\003\009O que esta pessoa faz?\\p\252\006\005\252\001\002\252\003\003Sou AGATHA, da ELITE DOS QUATRO.",
  ["sFameCheckerFlavorTextPointers[67]"] = "\252\001\008\252\003\009Tipo favorito de POKéMON?\\p\252\006\004\252\001\002\252\003\003Os POKéMON do tipo FANTASMA\\nda AGATHA são terrivelmente\\lassustadores de tão resistentes.",
  ["sFameCheckerFlavorTextPointers[68]"] = "\252\001\008\252\003\009Como é esta pessoa?\\p\252\006\004\252\001\002\252\003\003Aquela velha também tem o pavio\\nbem curto.\\pNão precisa de quase nada pra\\nfazer aquela mulher assustadora\\lcomeçar a gritar.",
  ["sFameCheckerFlavorTextPointers[69]"] = "\252\001\008\252\003\009Tem um boato…\\p\252\001\002\252\003\003Em sua juventude, AGATHA e o\\nPROFESSOR CARVALHO eram rivais\\lque lutavam pela supremacia como\\lTREINADORES.",
  ["sFameCheckerFlavorTextPointers[6]"] = "\252\001\008\252\003\009O que esta pessoa faz?\\p\252\006\004\252\001\002\252\003\003Se mostrar seus POKéMON para a\\nDAISY, ela dirá o quanto eles\\lgostam de você.\\pÀs vezes, ela até vai cuidar de\\num POKéMON para você.",
  ["sFameCheckerFlavorTextPointers[70]"] = "\252\001\008\252\003\009Família e amigos?\\p\252\006\005\252\001\002\252\003\003Ouvi dizer que CARVALHO tem muita\\nadmiração por você, criança.\\pAquele velho rabugento já foi\\nforte e bonito.\\pMas isso foi há décadas.\\nEle é só uma sombra do que era.",
  ["sFameCheckerFlavorTextPointers[71]"] = "\252\001\008\252\003\009Como é esta pessoa?\\p\252\006\005\252\001\002\252\003\003Pegue a AGATHA como exemplo.\\pEla detém o recorde de ser a\\nintegrante mais velha da\\lELITE DOS QUATRO.",
  ["sFameCheckerFlavorTextPointers[72]"] = "\252\001\008\252\003\009“O que essa pessoa faz?\\p\252\006\004\252\001\002\252\003\003”Eu lidero a ELITE DOS QUATRO.\\pPode me chamar de LANCE, o TREINADOR de dragoes.",
  ["sFameCheckerFlavorTextPointers[73]"] = "\252\001\008\252\003\009Tipo favorito de POKéMON?\\p\252\006\004\252\001\002\252\003\003Os dragões são POKéMON míticos.\\pEles são difíceis de capturar e\\ntreinar, mas seus poderes são\\lsuperiores.\\pEles são praticamente\\nindestrutíveis.",
  ["sFameCheckerFlavorTextPointers[74]"] = "\252\001\008\252\003\009Como é esta pessoa?\\p\252\006\005\252\001\002\252\003\003Ele luta pela justiça!\\nÉ estiloso e intenso!\\lEle é o melhor de todos, LANCE!",
  ["sFameCheckerFlavorTextPointers[75]"] = "\252\001\008\252\003\009Tem um boato…\\p\252\006\005\252\001\002\252\003\003Temos um cliente, LANCE, que\\naparece de vez em quando.\\pEle sempre compra capas.\\pSerá que ele tem muitas capas\\niguais em casa?",
  ["sFameCheckerFlavorTextPointers[76]"] = "\252\001\008\252\003\009Família e amigos?\\p\252\001\002\252\003\003Dizem que o avô de LANCE é o\\nancião de um famoso clã de\\lmestres de dragões.",
  ["sFameCheckerFlavorTextPointers[77]"] = "\252\001\008\252\003\009Família e amigos?\\p\252\006\004\252\001\002\252\003\003Pelo que ouvi dizer, o LANCE tem\\numa prima que é LÍDER de GINÁSIO\\lem algum lugar bem distante.",
  ["sFameCheckerFlavorTextPointers[78]"] = "\252\001\008\252\003\009O que esta pessoa faz?\\p\252\006\004\252\001\002\252\003\003Afinal, o BILL é mundialmente\\nconhecido como um POKéMANÍACO.\\pEle também inventou o Sistema\\nde Armazenamento POKéMON no PC.",
  ["sFameCheckerFlavorTextPointers[79]"] = "\252\001\008\252\003\009Tipo favorito de POKéMON?\\p\252\006\004\252\001\002\252\003\003O BILL tem muitos POKéMON!\\nE alguns deles são bem raros!",
  ["sFameCheckerFlavorTextPointers[7]"] = "\252\001\008\252\003\009Como é esta pessoa?\\p\252\006\005\252\001\002\252\003\003Mas acho que a pessoa que mais\\nconquista os POKéMON é a DAISY.",
  ["sFameCheckerFlavorTextPointers[80]"] = "\252\001\008\252\003\009Como é esta pessoa?\\p\252\006\004\252\001\002\252\003\003Ele é meu neto!\\pEle sempre gostou de colecionar\\ncoisas, até quando era criança!",
  ["sFameCheckerFlavorTextPointers[81]"] = "\252\001\008\252\003\009Tipo favorito de POKéMON?\\p\252\006\004\252\001\002\252\003\003O BILL é um POKéMANÍACO, então\\nele ama todos os tipos.\\pParece que o primeiro que ele\\ncapturou foi um ABRA.",
  ["sFameCheckerFlavorTextPointers[82]"] = "\252\001\008\252\003\009Família e amigos?\\p\252\006\004\252\001\002\252\003\003A cidade natal do BILL é GOLDENROD,\\nonde os pais dele ainda moram.\\pOuvi dizer que é uma cidade bem\\nmovimentada e cheia de vida.",
  ["sFameCheckerFlavorTextPointers[83]"] = "\252\001\008\252\003\009Tem um boato…\\p\252\006\004\252\001\002\252\003\003Dizem que o BILL não suporta leite\\nde jeito nenhum.",
  ["sFameCheckerFlavorTextPointers[84]"] = "\252\001\008\252\003\009O que esta pessoa faz?\\p\252\006\005\252\001\002\252\003\003Ele é muito bondoso.\\pEle cuida de POKéMON abandonados\\ne órfãos.",
  ["sFameCheckerFlavorTextPointers[85]"] = "\252\001\008\252\003\009Como é esta pessoa?\\p\252\006\004\252\001\002\252\003\003Esse velho apareceu de repente\\nno nosso ESCONDERIJO.\\pAí ele começou a reclamar\\ndizendo que a EQUIPE ROCKET\\lmaltrata os POKéMON.\\pEntão estamos só conversando\\nsobre isso como adultos.",
  ["sFameCheckerFlavorTextPointers[86]"] = "\252\001\008\252\003\009Como é esta pessoa?\\p\252\001\002\252\003\003REVISTA do FÃ POKéMON\\nSorteio mensal do grande prêmio!\\pO formulário de inscrição está…\\pSumiu! Foi recortado.\\nAlguém já deve ter se inscrito.",
  ["sFameCheckerFlavorTextPointers[87]"] = "\252\001\008\252\003\009Tem um boato…\\p\252\006\004\252\001\002\252\003\003Ouvi dizer que o SR. FUJI também\\nnão é nativo daqui.",
  ["sFameCheckerFlavorTextPointers[88]"] = "\252\001\008\252\003\009Família e amigos?\\p\252\001\002\252\003\003É uma foto de BLAINE e do\\nSR. FUJI.\\pEles estão lado a lado, sorrindo\\nde orelha a orelha.",
  ["sFameCheckerFlavorTextPointers[89]"] = "\252\001\008\252\003\009Como é esta pessoa?\\p\252\001\002\252\003\003Editor: O tímido SR. FUJI recusou\\nnossos pedidos de entrevista.\\pEle é um homem bondoso, adorado e\\nrespeitado na CIDADE DE LAVENDER.",
  ["sFameCheckerFlavorTextPointers[8]"] = "\252\001\008\252\003\009Como é esta pessoa?\\p\252\006\004\252\001\002\252\003\003Ela cuidava dos POKéMON com\\ntanto carinho… Era um anjinho.\\pO nome dela…\\nAcho que era DAISY.",
  ["sFameCheckerFlavorTextPointers[90]"] = "\252\001\008\252\003\009O que esta pessoa faz?\\p\252\006\004\252\001\002\252\003\003A EQUIPE ROCKET captura POKéMON\\ndo mundo inteiro.\\pEles são ferramentas importantes\\npara manter nosso empreendimento\\lcriminoso.\\pSou o líder, GIOVANNI!",
  ["sFameCheckerFlavorTextPointers[91]"] = "\252\001\008\252\003\009Tipo favorito de POKéMON?\\p\252\006\004\252\001\002\252\003\003Bandidos se apoderaram do nosso\\nprédio…\\pO CHEFE deles disse que estava\\nprocurando POKéMON fortes.",
  ["sFameCheckerFlavorTextPointers[92]"] = "\252\001\008\252\003\009Como é esta pessoa?\\p\252\006\004\252\001\002\252\003\003O CHEFE da EQUIPE ROCKET é muito\\ncruel!\\pPara ele, os POKéMON são só\\nferramentas.",
  ["sFameCheckerFlavorTextPointers[93]"] = "\252\001\008\252\003\009O que esta pessoa faz?\\p\252\006\004\252\001\002\252\003\003Bem-vind{o_a} ao meu esconderijo!\\pSerá assim até que eu possa\\nrestaurar a glória da EQUIPE\\lROCKET.",
  ["sFameCheckerFlavorTextPointers[94]"] = "\252\001\008\252\003\009O que esta pessoa faz?\\p\252\006\004\252\001\002\252\003\003Tá brincando?! GIOVANNI era o\\nLÍDER do GINÁSIO de VIRIDIAN?",
  ["sFameCheckerFlavorTextPointers[95]"] = "\252\001\008\252\003\009Família e amigos?\\p\252\006\004\252\001\002\252\003\003Você… Você não é filh{o_a} do\\nGIOVANNI, é?\\pNão, não pode ser!\\nO filho do GIOVANNI tem cabelo\\lvermelho.",
  ["sFameCheckerFlavorTextPointers[9]"] = "\252\001\008\252\003\009Família e amigos?\\p\252\001\002\252\003\003O PROFESSOR CARVALHO vive com\\nseus netos, DAISY e {RIVAL}.",
  ["sFameCheckerNameAndQuotesPointers[14]"] = "\252\001\008\252\003\009SR. FUJI",
  ["sFameCheckerNameAndQuotesPointers[16]"] = "\252\001\008\252\003\009De: PROFESSOR CARVALHO\\nPara: {PLAYER}\\p\252\006\004\252\001\002\252\003\003Por que os POKéMON competem e\\nbatalham tanto por você?\\pEles fazem isso porque conseguem\\nver o amor e a confiança que você\\ltem pelos POKéMON.\\pNunca se esqueça disso.",
  ["sFameCheckerNameAndQuotesPointers[17]"] = "\252\001\008\252\003\009De: DAISY\\nPara: {PLAYER}\\p\252\006\005\252\001\002\252\003\003Enquanto eu aproveitava calmamente\\nmeus lanches, você se tornou muito\\lhabilidos{o_a} e poderos{o_a}.\\pEspero que continue sendo {um_uma} {bom_boa}\\nrival para o meu irmãozinho.",
  ["sFameCheckerNameAndQuotesPointers[18]"] = "\252\001\008\252\003\009De: BROCK\\nPara: {PLAYER}\\p\252\006\004\252\001\002\252\003\003Neste nosso vasto mundo, deve\\nexistir muitos TREINADORES fortes.\\pVamos continuar treinando e nos\\ntornando cada vez mais fortes!",
  ["sFameCheckerNameAndQuotesPointers[19]"] = "\252\001\008\252\003\009De: MISTY\\nPara: {PLAYER}\\p\252\006\005\252\001\002\252\003\003Vou continuar treinando aqui neste\\nGINÁSIO.\\pQuando eu melhorar, adoraria colocar\\no pé na estrada e viajar.",
  ["sFameCheckerNameAndQuotesPointers[1]"] = "\252\001\008\252\003\009DAISY",
  ["sFameCheckerNameAndQuotesPointers[20]"] = "\252\001\008\252\003\009De: TEN. SURGE\\nPara: {PLAYER}\\p\252\006\004\252\001\002\252\003\003Ei, garot{o_a}!\\nVocê me eletrizou em nossa\\lbatalha!\\pEu não sabia que existiam\\nTREINADORES com tanta garra.\\pIsso me fez mudar de opinião\\nsobre você!",
  ["sFameCheckerNameAndQuotesPointers[21]"] = "\252\001\008\252\003\009De: ERIKA\\nPara: {PLAYER}\\p\252\006\005\252\001\002\252\003\003Fico muito feliz que existam\\nTREINADORES fortes como você.\\pSó de saber disso, já me sinto\\ninspirada e motivada a me esforçar.\\pPor favor, venha me visitar de novo.\\nRonc…",
  ["sFameCheckerNameAndQuotesPointers[22]"] = "\252\001\008\252\003\009De: KOGA\\nPara: {PLAYER}\\p\252\006\004\252\001\002\252\003\003Você e eu devemos mirar mais alto\\ne trabalhar para superar\\lnossos desafios.\\pAgora, preciso ir treinar minha filha.",
  ["sFameCheckerNameAndQuotesPointers[23]"] = "\252\001\008\252\003\009De: SABRINA\\nPara: {PLAYER}\\p\252\006\005\252\001\002\252\003\003O amor que você tem pelos seus\\nPOKéMON…\\pFoi um poder que nunca foi\\nsuperado pelo meu poder psíquico.",
  ["sFameCheckerNameAndQuotesPointers[24]"] = "\252\001\008\252\003\009De: BLAINE\\nPara: {PLAYER}\\p\252\006\004\252\001\002\252\003\003Meus POKéMON de fogo! Eles se\\ntornarão ainda mais poderosos!\\pAgora, um questionário. Quantos tipos\\nde POKéMON do tipo FOGO existem?",
  ["sFameCheckerNameAndQuotesPointers[25]"] = "\252\001\008\252\003\009De: LORELEI\\nPara: {PLAYER}\\p\252\006\005\252\001\002\252\003\003Eu precisava te agradecer pela\\nsua ajuda.\\pMas isso não tem nada a ver com\\nnossas batalhas.\\pÉ melhor você se cuidar na\\npróxima vez!",
  ["sFameCheckerNameAndQuotesPointers[26]"] = "\252\001\008\252\003\009De: BRUNO\\nPara: {PLAYER}\\p\252\006\004\252\001\002\252\003\003O superpoder seu e dos seus\\nPOKéMON eu senti na pele.\\pNa próxima, talvez eu deva te\\nmostrar como treinar a si mesmo.",
  ["sFameCheckerNameAndQuotesPointers[27]"] = "\252\001\008\252\003\009De: AGATHA\\nPara: {PLAYER}\\p\252\006\005\252\001\002\252\003\003Quando você envelhecer, não se\\natreva a amolecer como aquele\\lvelho gagá do CARVALHO!\\pSeja como eu e continue batalhando!",
  ["sFameCheckerNameAndQuotesPointers[28]"] = "\252\001\008\252\003\009De: LANCE\\nPara: {PLAYER}\\p\252\006\004\252\001\002\252\003\003Estou pensando em voltar para a\\nminha cidade natal.\\pQuero retreinar meus POKéMON do\\ntipo DRAGÃO e fortalecê-los.\\pGostaria de te convidar para a\\nminha cidade algum dia.",
  ["sFameCheckerNameAndQuotesPointers[29]"] = "\252\001\008\252\003\009De: BILL\\nPara: {PLAYER}\\p\252\006\004\252\001\002\252\003\003Olha! O CELIO não poupou elogios\\na você.\\pOuvir isso me deixa feliz.\\pQuando capturar algum POKéMON raro,\\nvenha me mostrar, tá? Promete!",
  ["sFameCheckerNameAndQuotesPointers[30]"] = "\252\001\008\252\003\009De: SR. FUJI\\nPara: {PLAYER}\\p\252\006\004\252\001\002\252\003\003Em vez de desejar a felicidade\\nsó dos seus POKéMON…\\p…Posso pedir que deseje a\\nfelicidade de todos os POKéMON?",
  ["sFameCheckerNameAndQuotesPointers[31]"] = "\252\001\008\252\003\009De: GIOVANNI\\nPara: {PLAYER}\\p\252\006\004\252\001\002\252\003\003Não há nada que eu deseje dizer\\na você.\\pVou me concentrar apenas em\\nmelhorar a mim mesmo, e mais nada.",
